import{_ as s}from"./chunks/3510_sync_control_mode_diagram.tNcLb1Xz.js";import{_ as l,o as n,a as e,b as p}from"./app.Zc0CUjTy.js";const t="/ascendc.github.io/assets/inter_core_aic_all_sync.DB06PmkS.png",r="/ascendc.github.io/assets/single_core_aiv_all_sync.Dfc9mRbc.png",o="/ascendc.github.io/assets/single_core_aic_aiv_sync_aiv_setflag.CbMVzNaB.png",c="/ascendc.github.io/assets/single_ai_core_aic_single_aiv_sync.UFYzqxTh.png",u=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"同步控制","link":"/api/SIMD-API/basic_api/sync_control/sync_control"},{"text":"核间同步","link":"/api/SIMD-API/basic_api/sync_control/inter_core_sync/inter_core_sync"},{"text":"关键特性说明","link":"/api/SIMD-API/basic_api/sync_control/inter_core_sync/key_features"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/sync_control/inter_core_sync/key_features.md","filePath":"api/SIMD-API/basic_api/sync_control/inter_core_sync/key_features.md","outlineHeaders":[{"level":2,"title":"核间同步flagId占用说明","slug":"核间同步flagId占用说明","link":"#核间同步flagId占用说明"},{"level":3,"title":"概述","slug":"概述","link":"#概述"},{"level":3,"title":"模式0、1、2的flagId占用","slug":"模式0、1、2的flagId占用","link":"#模式0、1、2的flagId占用"},{"level":3,"title":"模式4的flagId占用","slug":"模式4的flagId占用","link":"#模式4的flagId占用"},{"level":3,"title":"各接口限定条件说明","slug":"各接口限定条件说明","link":"#各接口限定条件说明"},{"level":4,"title":"SyncAll","slug":"SyncAll","link":"#SyncAll"},{"level":4,"title":"SetNextTaskStart / WaitPreTaskEnd","slug":"SetNextTaskStart-/-WaitPreTaskEnd","link":"#SetNextTaskStart-/-WaitPreTaskEnd"},{"level":4,"title":"Matmul","slug":"Matmul","link":"#Matmul"},{"level":4,"title":"TSCM","slug":"TSCM","link":"#TSCM"},{"level":4,"title":"DataCopy（GM→L1）","slug":"DataCopy（GM→L1）","link":"#DataCopy（GM→L1）"},{"level":2,"title":"各个核间同步控制实现原理","slug":"各个核间同步控制实现原理","link":"#各个核间同步控制实现原理"},{"level":2,"title":"多AI Core中AIC或者AIV全核同步（模式0）","slug":"多AI-Core中AIC或者AIV全核同步（模式0）","link":"#多AI-Core中AIC或者AIV全核同步（模式0）"},{"level":2,"title":"单个AI Core中AIV全核同步（模式1）","slug":"单个AI-Core中AIV全核同步（模式1）","link":"#单个AI-Core中AIV全核同步（模式1）"},{"level":2,"title":"单个AI Core中AIC与AIV全核同步（模式2）","slug":"单个AI-Core中AIC与AIV全核同步（模式2）","link":"#单个AI-Core中AIC与AIV全核同步（模式2）"},{"level":2,"title":"单个AI Core中AIC与单个AIV同步（模式4）","slug":"单个AI-Core中AIC与单个AIV同步（模式4）","link":"#单个AI-Core中AIC与单个AIV同步（模式4）"}],"lastUpdated":1789719271000}'),i={name:"api/SIMD-API/basic_api/sync_control/inter_core_sync/key_features.md"};function d(I,a,C,g,A,_){return n(),e("div",null,[...a[0]||(a[0]=[p('<div><article class="markdown-body"><h1>关键特性说明<a id="inter_core_sync_key_features"></a></h1><p>本文档主要介绍核间同步的两个关键事项：</p><ul><li>核间同步flagId的占用情况，说明各接口内部占用的flagId取值范围，帮助开发者在使用CrossCoreSetFlag/CrossCoreWaitFlag时避免flagId冲突。</li><li>各核间同步控制模式的实现原理，配合时序图介绍模式0、1、2、4各自的工作机制。</li></ul><h2 id="核间同步flagId占用说明">核间同步flagId占用说明<a id="inter_core_sync_flagid_usage"></a><a class="header-anchor" href="#核间同步flagId占用说明">​</a></h2><h3 id="概述">概述<a class="header-anchor" href="#概述">​</a></h3><p>开发者使用<a href="CrossCoreSetFlag_ISASI.html">CrossCoreSetFlag</a>和<a href="CrossCoreWaitFlag_ISASI.html">CrossCoreWaitFlag</a>接口进行核间同步时，需要传入核间同步标记<strong>flagId</strong>，每个flagId对应一个用于控制同步的计数器。</p><p>部分接口的内部实现也会占用一部分flagId。当开发者同时使用这些接口与CrossCoreSetFlag/CrossCoreWaitFlag时，若flagId发生冲突（即相互独立的同步操作复用了同一个flagId），其对应的计数器会被错误地共享和修改，导致核间同步行为异常：可能出现阻塞无法解除而使程序卡死，或同步提前完成、阻塞提前解除而导致计算结果错误。</p><p>因此，当开发者同时调用CrossCoreSetFlag/CrossCoreWaitFlag与这些占用flagId的接口时，应<strong>避开各接口内部已占用的flagId</strong>，选用未被占用的flagId。</p><p>核间同步分为<strong>模式0、1、2</strong>与<strong>模式4</strong>，两者的底层硬件指令不同，flagId相互独立，因此各接口flagId的占用情况按<strong>所属模式</strong>和<strong>NPU架构版本</strong>分别参见<a href="#inter_core_sync_flagid_mode012">模式0、1、2的flagId占用</a>和<a href="#inter_core_sync_flagid_mode4">模式4的flagId占用</a>。</p><h3 id="模式0、1、2的flagId占用">模式0、1、2的flagId占用<a id="inter_core_sync_flagid_mode012"></a><a class="header-anchor" href="#模式0、1、2的flagId占用">​</a></h3><p><strong>表1</strong> 模式0、1、2flagId占用情况</p><table><thead><tr><th align="left">接口</th><th align="left">限定条件</th><th align="left">占用flagId</th><th align="left">各计算核占用情况</th><th align="left">NPU架构版本</th></tr></thead><tbody><tr><td align="left"><a href="SyncAll.html">SyncAll</a></td><td align="left"><code>isAIVOnly=true</code></td><td align="left">14</td><td align="left">AIV：14</td><td align="left">2201、3510</td></tr><tr><td align="left"><a href="SyncAll.html">SyncAll</a></td><td align="left"><code>isAIVOnly=false</code></td><td align="left">11、12、13</td><td align="left">AIC：11、12、13；AIV：12、13</td><td align="left">2201、3510</td></tr><tr><td align="left"><a href="../inter_task_sync/SetNextTaskStart.html">SetNextTaskStart</a></td><td align="left">SuperKernel子核函数（Kernel）中调用</td><td align="left">11、14</td><td align="left">AIC：11；AIV：14</td><td align="left">2201、3510</td></tr><tr><td align="left"><a href="../inter_task_sync/WaitPreTaskEnd.html">WaitPreTaskEnd</a></td><td align="left">SuperKernel子核函数（Kernel）中调用</td><td align="left">11、12、13、14</td><td align="left">AIC：11、12、13；AIV：12、13、14</td><td align="left">2201、3510</td></tr><tr><td align="left"><a href="../../../adv_api/cube_compute/Matmul_Kernel/Matmul_Kernel.html">Matmul</a></td><td align="left">定义N个Matmul对象</td><td align="left"><code>[0, 2N-1]</code></td><td align="left">AIV/AIC按对象与subBlock分配</td><td align="left">2201</td></tr><tr><td align="left"><a href="../../../adv_api/cube_compute/Matmul_Kernel/Matmul_Kernel.html">Matmul</a></td><td align="left">SuperKernel融合场景（<a href="../../tool_interface/system_resources_and_variables/GetTaskRatio.html">GetTaskRatio</a>返回2，即1:2配比）</td><td align="left">15</td><td align="left">AIV：15</td><td align="left">2201</td></tr></tbody></table><h3 id="模式4的flagId占用">模式4的flagId占用<a id="inter_core_sync_flagid_mode4"></a><a class="header-anchor" href="#模式4的flagId占用">​</a></h3><p><strong>表2</strong> 模式4flagId占用情况</p><table><thead><tr><th align="left">接口</th><th align="left">限定条件</th><th align="left">占用flagId</th><th align="left">各计算核占用情况</th><th align="left">NPU架构版本</th></tr></thead><tbody><tr><td align="left"><a href="SyncAll.html">SyncAll</a></td><td align="left"><code>isAIVOnly=false</code>（核函数（Kernel）使用<code>__mix__(1, 2)</code>修饰时）</td><td align="left">12、13、28、29</td><td align="left">AIC：12、13、28、29；AIV：12、13</td><td align="left">3510</td></tr><tr><td align="left"><a href="../inter_task_sync/WaitPreTaskEnd.html">WaitPreTaskEnd</a></td><td align="left">SuperKernel子核函数（Kernel）中调用</td><td align="left">12、13、28、29</td><td align="left">AIC：12、13、28、29；AIV：12、13</td><td align="left">3510</td></tr><tr><td align="left"><a href="../../../adv_api/cube_compute/Matmul_Kernel/Matmul_Kernel.html">Matmul</a></td><td align="left">定义N个<a href="../../../adv_api/cube_compute/Matmul_Kernel/REGIST_MATMUL_OBJ.html">Matmul对象</a></td><td align="left"><code>[0, N+17]</code></td><td align="left">AIC/AIV按对象、eventType、subBlock分配</td><td align="left">3510</td></tr><tr><td align="left"><a href="../../../adv_api/cube_compute/Matmul_Kernel/Matmul_Kernel.html">Matmul</a></td><td align="left">A矩阵和B矩阵同时开启<a href="../../../adv_api/cube_compute/Matmul_Kernel/Matmul_usage.html#p84551411817">IBSHARE</a>的场景</td><td align="left">15</td><td align="left">AIV：15</td><td align="left">3510</td></tr><tr><td align="left"><a href="../../resource_management/TSCM/TSCM.html">TSCM</a></td><td align="left">从UB发起的L1 Buffer（TSCM）队列</td><td align="left">0~11（从11向下逐个分配）</td><td align="left">AIV</td><td align="left">3510</td></tr><tr><td align="left"><a href="../../cube_compute_ISASI/cube_compute_load/DataCopy_GMToL1_continuous.html">DataCopy（GM→L1）</a></td><td align="left">无</td><td align="left">1、17</td><td align="left">AIC：1、17；AIV：1</td><td align="left">3510</td></tr></tbody></table><h3 id="各接口限定条件说明">各接口限定条件说明<a class="header-anchor" href="#各接口限定条件说明">​</a></h3><h4 id="SyncAll">SyncAll<a class="header-anchor" href="#SyncAll">​</a></h4><ul><li><p><strong>isAIVOnly=true</strong>：纯Vector算子的全核同步，占用模式0、1、2的flagId为14（AIV）。</p></li><li><p><strong>isAIVOnly=false</strong>：Mix（包含Cube和Vector计算）算子的全核同步，占用情况随NPU架构与核函数（Kernel）类型不同：</p><ul><li><strong>2201架构</strong>：占用模式0、1、2的flagId为11、12、13。</li><li><strong>3510架构</strong>： <ul><li>核函数（Kernel）使用<code>__mix__(1, 1)</code>修饰时，占用模式0、1、2的flagId为11、12、13。</li><li>核函数（Kernel）使用<code>__mix__(1, 2)</code>修饰时，占用模式0、1、2的flagId为11，以及模式4的flagId为12、13、28、29。</li></ul></li></ul><p>以上<code>isAIVOnly</code>模板参数的说明参见<a href="SyncAll.html">SyncAll</a>；<code>__mix__(1, 1)</code>/<code>__mix__(1, 2)</code>修饰符的说明参见<a href="../../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html#%E5%87%BD%E6%95%B0%E6%89%A7%E8%A1%8C%E7%A9%BA%E9%97%B4%E9%99%90%E5%AE%9A%E7%AC%A6">函数执行空间限定符</a>。</p></li></ul><h4 id="SetNextTaskStart-/-WaitPreTaskEnd">SetNextTaskStart / WaitPreTaskEnd<a class="header-anchor" href="#SetNextTaskStart-/-WaitPreTaskEnd">​</a></h4><ul><li>二者为<strong>SuperKernel</strong>场景专用接口，仅在算子以<a href="../../../../../guide/programming_guide/advanced_programming/super_kernel/principles.html">SuperKernel</a>方式融合、且子核函数（Kernel）中调用时才生效。</li><li><strong>SetNextTaskStart</strong>：占用模式0、1、2的flagId为11（AIC）、14（AIV）。参见<a href="../inter_task_sync/SetNextTaskStart.html">SetNextTaskStart</a>。</li><li><strong>WaitPreTaskEnd</strong>：参见<a href="../inter_task_sync/WaitPreTaskEnd.html">WaitPreTaskEnd</a>。 <ul><li><strong>2201架构</strong>：占用模式0、1、2的flagId为11、12、13、14。</li><li><strong>3510架构</strong>：占用模式0、1、2的flagId为11、12、13、14，以及模式4的flagId为12、13、28、29。</li></ul></li></ul><h4 id="Matmul">Matmul<a class="header-anchor" href="#Matmul">​</a></h4><ul><li>占用flagId的范围与定义的<strong>Matmul对象数目N</strong>相关（N最大为4），并且随NPU架构不同而不同，参见<a href="../../../adv_api/cube_compute/Matmul_Kernel/REGIST_MATMUL_OBJ.html#%E7%BA%A6%E6%9D%9F%E8%AF%B4%E6%98%8E">REGIST_MATMUL_OBJ</a>。</li><li><strong>2201架构</strong>：占用模式0、1、2的flagId为[0, 2N-1]（N=4时占用<code>[0,7]</code>）；SuperKernel融合（1:2配比，即<a href="../../tool_interface/system_resources_and_variables/GetTaskRatio.html">GetTaskRatio</a>返回2）场景下还占用flagId为15。</li><li><strong>3510架构</strong>：占用模式4的flagId为[0, N+17]（N=4时占用<code>[0,21]</code>）；A矩阵和B矩阵同时开启<a href="../../../adv_api/cube_compute/Matmul_Kernel/Matmul_usage.html#p84551411817">IBSHARE</a>的场景下还占用flagId为15。</li></ul><h4 id="TSCM">TSCM<a class="header-anchor" href="#TSCM">​</a></h4><ul><li>仅当使用从UB发起的L1 Buffer（TSCM）队列时才触发，参见<a href="../../resource_management/TSCM/TSCM.html">TSCM</a>。</li><li>占用模式4的flagId，范围为<strong>0~11</strong>：第1个TSCM队列占用11，第2个占用10，依次向下递减分配，最多可分配到0。</li></ul><h4 id="DataCopy（GM→L1）">DataCopy（GM→L1）<a class="header-anchor" href="#DataCopy（GM→L1）">​</a></h4><ul><li>在<strong>3510架构</strong>下占用模式4的flagId为1、17（AIC：1、17；AIV：1）。参见<a href="../../cube_compute_ISASI/cube_compute_load/DataCopy_GMToL1_continuous.html">DataCopy（GMToL1连续数据搬运）</a>。</li></ul><h2 id="各个核间同步控制实现原理">各个核间同步控制实现原理<a id="sync_control_mode"></a><a class="header-anchor" href="#各个核间同步控制实现原理">​</a></h2><p>如图1所示，本章节将配合时序图介绍CrossCoreSetFlag和CrossCoreWaitFlag配合使用时支持的四种同步控制模式各自实现的原理。</p><ul><li>模式0：AI Core核间的同步控制。对于AIC全核场景，同步所有的AIC核，直到所有的AIC核都执行到CrossCoreSetFlag时，CrossCoreWaitFlag后续的全部流水或者由模板参数pipe指定的流水（与NPU架构有关）中的指令才会执行；对于AIV全核场景，同步所有的AIV核，直到所有的AIV核都执行到CrossCoreSetFlag时，CrossCoreWaitFlag后续的全部流水或者由模板参数pipe指定的流水（与NPU架构有关）中的指令才会执行。</li><li>模式1：AI Core内部，AIV核之间的同步控制。如果两个AIV核都运行了CrossCoreSetFlag，CrossCoreWaitFlag后续的全部流水或者由模板参数pipe指定的流水（与NPU架构有关）中的指令才会执行。</li><li>模式2：AI Core内部，AIC与AIV之间的同步控制。在AIC核执行CrossCoreSetFlag之后，两个AIV上CrossCoreWaitFlag后续的全部流水或者由模板参数pipe指定的流水（与NPU架构有关）中的指令才会继续执行；两个AIV都执行CrossCoreSetFlag后，AIC上CrossCoreWaitFlag后续的全部流水或者由模板参数pipe指定的流水（与NPU架构有关）中的指令才能执行。</li><li>模式4：AI Core内部，AIC与单个AIV之间的同步控制。在AIC核执行CrossCoreSetFlag之后，单个AIV上CrossCoreWaitFlag后续的由模板参数pipe指定的流水中的指令才会继续执行；单个AIV执行CrossCoreSetFlag后，AIC上CrossCoreWaitFlag后续的由模板参数pipe指定的流水中的指令才能执行。该模式仅在<a href="../../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html">NPU架构版本3510</a>上支持。</li></ul><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明 模式0、1、2下<code>CrossCoreWaitFlag</code>阻塞的流水类型因NPU架构而异：</p><ul><li>在<a href="../../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html">NPU架构版本2201</a>上，<code>CrossCoreWaitFlag</code>传入的<code>pipe</code>参数无效，无论取值为何都默认阻塞全部流水的后续指令，建议省略<code>pipe</code>参数并使用默认值。</li><li>在<a href="../../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html">NPU架构版本3510</a>上，<code>CrossCoreWaitFlag</code>传入的<code>pipe</code>参数生效，阻塞由模板参数<code>pipe</code>指定的流水的后续指令。</li></ul></div><p><strong>图1</strong> 同步控制模式示意图<a id="sync_control_mode_diagram"></a><br><img src="'+s+`" alt title="同步控制模式示意图"></p><p>下述同步特性均以如下场景配置为例：核函数（Kernel）使用<code>__mix__(1, 2)</code>修饰，即每个AI Core包含1个AIC和2个AIV，并设置逻辑核数<code>numBlocks=2</code>，即共启动2个AI Core，因此存在2个AIC和4个AIV。为便于描述，将2个AIC分别编号为AIC0、AIC1；AI Core0中的2个AIV分别编号为AIV0-0、AIV0-1，AI Core1中的2个AIV分别编号为AIV1-0、AIV1-1。<strong>各核中与<code>flagId</code>对应的计数器初始值均为0。</strong></p><div data-filter="A3,910b"><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>以下针对模式0、1、2的描述，仅针对<a href="../../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html">NPU架构版本2201</a>有效，此时<code>CrossCoreWaitFlag</code>传入的<code>pipe</code>参数无效，因此采用默认值，默认阻塞全部流水的后续指令。</p></div><h2 id="多AI-Core中AIC或者AIV全核同步（模式0）">多AI Core中AIC或者AIV全核同步（模式0）<a id="multi_ai_core_aic_aiv_full_sync"></a><a class="header-anchor" href="#多AI-Core中AIC或者AIV全核同步（模式0）">​</a></h2><p>多AI Core中AIC或者AIV全核同步需要配套使用模式0的<a href="CrossCoreSetFlag_ISASI.html">CrossCoreSetFlag</a>和<a href="CrossCoreWaitFlag_ISASI.html">CrossCoreWaitFlag</a>接口。该场景可细分为两类：</p><ul><li><p>2个AI Core中的2个AIC进行全核同步。</p><p>当2个AIC都执行完CrossCoreSetFlag时，每个AIC对应flagId的计数器增加1。若AIC该flagId的计数器为非0，被CrossCoreWaitFlag所阻塞的所有流水中的指令才会执行下去，该flagId的计数器减去1。</p><p>对于每个AIC，CrossCoreSetFlag和CrossCoreWaitFlag都必须配对使用。</p></li><li><p>2个AI Core中的4个AIV进行全核同步。</p><p>当4个AIV都执行完CrossCoreSetFlag时，每个AIV核对应flagId的计数器增加1。若AIV该flagId的计数器为非0，被CrossCoreWaitFlag所阻塞的所有流水中的指令才会执行下去，该flagId的计数器减去1。</p><p>对于每个AIV，CrossCoreSetFlag和CrossCoreWaitFlag都必须配对使用。</p></li></ul><p>以图2为例，演示2个AI Core中的2个AIC（AIC0、AIC1）进行全核同步，代码片段如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 进行核间同步时，即使只有AIC参与同步也不能用__cube__修饰核函数（Kernel），具体原因请参考CrossCoreSetFlag的约束说明。</span>
<span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">ASCEND_IS_AIC</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="c1">// 每个核都应该有类似如下的成对调用CrossCoreSetFlag和CrossCoreWaitFlag。</span>
<span class="w">    </span><span class="c1">// modeId必须配置为0，flagId要一致；CrossCoreWaitFlag的pipe使用默认值。</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">CrossCoreSetFlag</span><span class="o">&lt;</span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="n">PIPE_M</span><span class="o">&gt;</span><span class="p">(</span><span class="mi">0</span><span class="p">);</span><span class="w">       </span><span class="c1">// 待前置PIPE_M流水任务完成后，通知调度模块。</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">CrossCoreWaitFlag</span><span class="o">&lt;</span><span class="mi">0</span><span class="o">&gt;</span><span class="p">(</span><span class="mi">0</span><span class="p">);</span><span class="w">              </span><span class="c1">// 直到所有AIC都完成前置PIPE_M流水，调度模块更新flagId=0的计数器后，解除所有流水后续指令的阻塞。</span>
<span class="p">}</span>
</code></pre></div><p>AIC0中在执行CrossCoreWaitFlag后，此时AIC0 flagId=0的计数器为0，后续所有流水中的指令全部被阻塞，需要等到2个AIC核均执行完CrossCoreSetFlag。</p><p>AIC1的CrossCoreSetFlag执行完后，此时调度模块感知到2个AIC均已执行完CrossCoreSetFlag，因此所有AIC各自的flagId=0的计数器值增加为1。AIC0和AIC1检测到各自对应的flagId=0的计数器变为1，都解除所有流水后续指令的阻塞，继续执行后续指令，并且将计数器值减去1。</p><p><strong>图2</strong> 模式0：多AI Core中AIC全核同步<a id="multi_ai_core_aic_full_sync"></a><br><img src="`+t+`" alt title="多AI_Core中AIC全核同步"></p><h2 id="单个AI-Core中AIV全核同步（模式1）">单个AI Core中AIV全核同步（模式1）<a id="single_ai_core_aiv_full_sync"></a><a class="header-anchor" href="#单个AI-Core中AIV全核同步（模式1）">​</a></h2><p>该场景需要配套使用模式1的<a href="CrossCoreSetFlag_ISASI.html">CrossCoreSetFlag</a>和<a href="CrossCoreWaitFlag_ISASI.html">CrossCoreWaitFlag</a>接口。</p><p>1个AI Core中的2个AIV进行全核同步。当2个AIV全部都执行完CrossCoreSetFlag时，每个AIV对应flagId的计数器增加1。若AIV该flagId的计数器为非0，被CrossCoreWaitFlag所阻塞的所有流水中的指令才会执行下去，该flagId的计数器减去1。对于每个AIV，CrossCoreSetFlag和CrossCoreWaitFlag都必须配对使用。</p><div class="callout callout-caution"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M4.47.22A.749.749 0 0 1 5 0h6c.199 0 .389.079.53.22l4.25 4.25c.141.14.22.331.22.53v6a.749.749 0 0 1-.22.53l-4.25 4.25A.749.749 0 0 1 11 16H5a.749.749 0 0 1-.53-.22L.22 11.53A.749.749 0 0 1 0 11V5c0-.199.079-.389.22-.53Zm.84 1.28L1.5 5.31v5.38l3.81 3.81h5.38l3.81-3.81V5.31L10.69 1.5ZM8 4a.75.75 0 0 1 .75.75v3.5a.75.75 0 0 1-1.5 0v-3.5A.75.75 0 0 1 8 4Zm0 8a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>注意</p><p>该模式中，不同AI Core的AIV核之间不会互相影响同步。</p></div><p>以图3为例，演示第0个AI Core中的2个AIV（AIV0-0、AIV0-1）进行全核同步，代码片段如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 进行核间同步时，即使只有AIV参与同步也不能用__vector__修饰核函数（Kernel），具体原因请参考CrossCoreSetFlag的约束说明。</span>
<span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">ASCEND_IS_AIV</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">AscendC</span><span class="o">::</span><span class="w"> </span><span class="n">GetBlockIdx</span><span class="p">()</span><span class="w"> </span><span class="o">&lt;=</span><span class="w"> </span><span class="mi">1</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="c1">// 参与同步的2个AIV属于第0个AI Core。</span>
<span class="w">        </span><span class="c1">// 每个AIV都应该有类似如下的成对调用CrossCoreSetFlag和CrossCoreWaitFlag。</span>
<span class="w">        </span><span class="c1">// modeId必须配置为1，flagId要一致；CrossCoreWaitFlag的pipe使用默认值。</span>
<span class="w">        </span><span class="n">AscendC</span><span class="o">::</span><span class="n">CrossCoreSetFlag</span><span class="o">&lt;</span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="n">PIPE_MTE3</span><span class="o">&gt;</span><span class="p">(</span><span class="mi">0</span><span class="p">);</span><span class="w">       </span><span class="c1">// 待前置PIPE_MTE3流水任务完成后，通知调度模块。</span>
<span class="w">        </span><span class="n">AscendC</span><span class="o">::</span><span class="n">CrossCoreWaitFlag</span><span class="o">&lt;</span><span class="mi">1</span><span class="o">&gt;</span><span class="p">(</span><span class="mi">0</span><span class="p">);</span><span class="w">                  </span><span class="c1">// 直到该AI Core中的所有AIV都完成前置PIPE_MTE3流水，调度模块更新flagId=0的计数器后，解除所有流水后续指令的阻塞。</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>
</code></pre></div><p>AIV0-0中在执行CrossCoreWaitFlag后，此时AIV0-0 flagId=0的计数器为0，后续所有流水中的指令全部被阻塞，需要等到2个AIV均执行完CrossCoreSetFlag。</p><p>AIV0-1的CrossCoreSetFlag执行完后，此时调度模块感知到2个AIV均已执行完CrossCoreSetFlag，因此将AIV0-0和AIV0-1各自的flagId=0的计数器值增加为1。AIV0-0和AIV0-1检测到各自对应的flagId=0的计数器变为1，都解除所有流水后续指令的阻塞，继续执行后续指令，并且将计数器值减去1。</p><p><strong>图3</strong> 模式1：单个AI Core中AIV全核同步<a id="single_ai_core_aiv_full_sync_diagram"></a><br><img src="`+r+`" alt title="单AI_Core中AIV全核同步"></p><h2 id="单个AI-Core中AIC与AIV全核同步（模式2）">单个AI Core中AIC与AIV全核同步（模式2）<a id="single_ai_core_aic_aiv_full_sync"></a><a class="header-anchor" href="#单个AI-Core中AIC与AIV全核同步（模式2）">​</a></h2><p>单个AI Core中AIC与AIV全核同步需要配套使用模式2的<a href="CrossCoreSetFlag_ISASI.html">CrossCoreSetFlag</a>和<a href="CrossCoreWaitFlag_ISASI.html">CrossCoreWaitFlag</a>接口。该场景可细分为两类：</p><ul><li><p>1个AI Core中的AIC执行CrossCoreSetFlag，对应的2个AIV都执行CrossCoreWaitFlag。</p><p>当AIC执行完CrossCoreSetFlag时，2个AIV对应flagId的计数器增加1。若AIV该flagId的计数器为非0，则解除AIV所有流水后续指令的阻塞，CrossCoreWaitFlag后的指令继续发射，该flagId的计数器减去1。</p><p>总计AIC 1次调用CrossCoreSetFlag，对应2个AIV各1次CrossCoreWaitFlag才算配对使用。</p></li><li><p>1个AI Core中的2个AIV都执行CrossCoreSetFlag，对应的AIC执行CrossCoreWaitFlag。</p><p>当2个AIV全都执行完CrossCoreSetFlag时，AIC对应flagId的计数器增加1。若AIC该flagId的计数器为非0，则解除AIC所有流水后续指令的阻塞，CrossCoreWaitFlag后的指令继续发射，该flagId的计数器减去1。</p><p>总计2个AIV各1次CrossCoreSetFlag，对应AIC 1次调用CrossCoreWaitFlag才算配对使用。</p></li></ul><p>以图4为例，演示第0个AI Core中AIC0与AIV0-0、AIV0-1进行同步（AIV发起CrossCoreSetFlag），代码片段如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// AIC和AIV均参与核间同步，需分别使用对应宏包裹代码段，具体原因请参考CrossCoreSetFlag的约束说明。</span>
<span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">ASCEND_IS_AIV</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">AscendC</span><span class="o">::</span><span class="w"> </span><span class="n">GetBlockIdx</span><span class="p">()</span><span class="w"> </span><span class="o">&lt;=</span><span class="w"> </span><span class="mi">1</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="c1">// 参与同步的AIV属于第0个AI Core。</span>
<span class="w">        </span><span class="c1">// 每个AIV都应该有类似如下的CrossCoreSetFlag调用。</span>
<span class="w">        </span><span class="c1">// modeId必须配置为2，flagId要一致。</span>
<span class="w">        </span><span class="n">AscendC</span><span class="o">::</span><span class="n">CrossCoreSetFlag</span><span class="o">&lt;</span><span class="mi">2</span><span class="p">,</span><span class="w"> </span><span class="n">PIPE_MTE3</span><span class="o">&gt;</span><span class="p">(</span><span class="mi">0</span><span class="p">);</span><span class="w">       </span><span class="c1">// 待前置PIPE_MTE3流水任务完成后，通知调度模块。必须由所有AIV执行。</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>
<span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">ASCEND_IS_AIC</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">AscendC</span><span class="o">::</span><span class="w"> </span><span class="n">GetBlockIdx</span><span class="p">()</span><span class="w"> </span><span class="o">==</span><span class="w"> </span><span class="mi">0</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="c1">// 参与同步的AIC属于第0个AI Core。</span>
<span class="w">        </span><span class="c1">// AIC需要有类似如下的CrossCoreWaitFlag调用。</span>
<span class="w">        </span><span class="c1">// CrossCoreWaitFlag的pipe使用默认值。</span>
<span class="w">        </span><span class="n">AscendC</span><span class="o">::</span><span class="n">CrossCoreWaitFlag</span><span class="o">&lt;</span><span class="mi">2</span><span class="o">&gt;</span><span class="p">(</span><span class="mi">0</span><span class="p">);</span><span class="w">                 </span><span class="c1">// 直到该AI Core中的所有AIV都完成前置PIPE_MTE3流水，调度模块更新flagId=0的计数器后，AIC解除所有流水后续指令的阻塞。</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>
</code></pre></div><p>AIC0中在执行CrossCoreWaitFlag后，此时AIC0 flagId=0的计数器为0，后续所有流水中的指令全部被阻塞，需要等到2个AIV均执行完CrossCoreSetFlag。</p><p>当AIV0-1的CrossCoreSetFlag在Vector指令1执行完后，前置PIPE_V的指令全部完成，CrossCoreSetFlag执行完成，但是此时AIV0-0未执行CrossCoreSetFlag。因此AIC0 flagId=0的计数器还是为0，AIC的所有流水中的指令依然被阻塞。</p><p>当AIV0-0的Vector指令1、2全部执行完毕后，前置PIPE_V的指令全部完成，CrossCoreSetFlag生效。此时调度模块感知到2个AIV均已执行完CrossCoreSetFlag，因此将AIC0 flagId=0的计数器值增加为1。AIC0检测到对应的flagId=0的计数器变为1，则AIC0核解除所有流水后续指令的阻塞，继续执行后续指令Matrix指令2，并且将计数器值减去1。</p><p><strong>图4</strong> 模式2：单个AI Core中AIC与AIV全核同步（AIV进行CrossCoreSetFlag）<a id="single_ai_core_aic_aiv_full_sync_diagram"></a><br><img src="`+o+`" alt title="单AI_Core中AIC与AIV全核同步（AIV进行CrossCoreSetFlag）"></p></div><div data-filter="950"><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>模式4仅在<a href="../../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html">NPU架构版本3510</a>上支持，此时<code>CrossCoreWaitFlag</code>传入的<code>pipe</code>参数生效，阻塞由<strong>模板参数pipe配置的指定流水</strong>的后续指令。</p></div><h2 id="单个AI-Core中AIC与单个AIV同步（模式4）">单个AI Core中AIC与单个AIV同步（模式4）<a id="single_ai_core_aic_single_aiv_sync"></a><a class="header-anchor" href="#单个AI-Core中AIC与单个AIV同步（模式4）">​</a></h2><p>单个AI Core中AIC与单个AIV同步需要配套使用模式4的<a href="CrossCoreSetFlag_ISASI.html">CrossCoreSetFlag</a>和<a href="CrossCoreWaitFlag_ISASI.html">CrossCoreWaitFlag</a>接口。该场景可细分为两类：</p><ul><li><p>1个AI Core中的AIC执行CrossCoreSetFlag，对应的AIV执行CrossCoreWaitFlag。</p><p>当AIC执行完CrossCoreSetFlag时，AIV对应flagId的计数器增加1。若AIV该flagId的计数器为非0，则解除AIV由模板参数pipe指定的流水的阻塞，CrossCoreWaitFlag后的指令继续发射，该flagId的计数器减去1。</p><p>总计AIC 1次调用CrossCoreSetFlag，单个AIV完成一次CrossCoreWaitFlag才算配对使用。</p></li><li><p>1个AI Core中的1个AIV执行CrossCoreSetFlag，对应的AIC执行CrossCoreWaitFlag。</p><p>当AIV执行完CrossCoreSetFlag时，AIC对应flagId的计数器增加1。若AIC该flagId的计数器为非0，则解除AIC由模板参数pipe指定的流水的阻塞，CrossCoreWaitFlag后的指令继续发射，该flagId的计数器减去1。</p><p>总计单个AIV 1次CrossCoreSetFlag，对应AIC 1次调用CrossCoreWaitFlag才算配对使用。</p></li></ul><p>以图5为例，演示第0个AI Core中AIV0-1与AIC0进行同步（AIV0-1发起CrossCoreSetFlag），代码片段如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// AIC和AIV均参与核间同步，需分别使用对应宏包裹代码段，具体原因请参考CrossCoreSetFlag的约束说明。</span>
<span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">ASCEND_IS_AIV</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="w"> </span><span class="n">GetBlockIdx</span><span class="p">()</span><span class="w"> </span><span class="o">==</span><span class="w"> </span><span class="mi">1</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="c1">// modeId必须配置为4。对于flagId，AIV0-1上的0-15对应AIC0上的16-31。</span>
<span class="w">        </span><span class="n">AscendC</span><span class="o">::</span><span class="n">CrossCoreSetFlag</span><span class="o">&lt;</span><span class="mi">4</span><span class="p">,</span><span class="w"> </span><span class="n">PIPE_MTE3</span><span class="o">&gt;</span><span class="p">(</span><span class="mi">0</span><span class="p">);</span><span class="w">   </span><span class="c1">// 待AIV0-1上前置PIPE_MTE3流水任务完成后，通知调度模块。</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>
<span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">ASCEND_IS_AIC</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="w"> </span><span class="n">GetBlockIdx</span><span class="p">()</span><span class="w"> </span><span class="o">==</span><span class="w"> </span><span class="mi">0</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="c1">// modeId必须配置为4，flagId要一致；CrossCoreWaitFlag的pipe参数生效，此处阻塞由模板参数pipe配置的指定流水（PIPE_FIX）。</span>
<span class="w">        </span><span class="n">AscendC</span><span class="o">::</span><span class="n">CrossCoreWaitFlag</span><span class="o">&lt;</span><span class="mi">4</span><span class="p">,</span><span class="w"> </span><span class="n">PIPE_FIX</span><span class="o">&gt;</span><span class="p">(</span><span class="mi">16</span><span class="p">);</span><span class="w">       </span><span class="c1">// 阻塞由模板参数pipe配置的指定流水（此处为PIPE_FIX）的后续指令，直到该AI Core中的AIV0-1都完成前置PIPE_MTE3流水，调度模块更新flagId=16的计数器后，AIC0解除阻塞。</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>
</code></pre></div><p>AIC0中在执行CrossCoreWaitFlag后，此时AIC0 flagId=16的计数器为0，后续由模板参数pipe配置的指定流水（此处为PIPE_FIX）的指令全部被阻塞，需要等到1个AIV执行完CrossCoreSetFlag。</p><ul><li>AIV0-0不需要执行CrossCoreSetFlag，也不需要参与同步。</li><li>AIV0-1的PIPE_MTE3指令全部执行完毕后，CrossCoreSetFlag生效。此时调度模块感知1个AIV已执行完CrossCoreSetFlag，因此将AIC0 flagId=16的计数器值增加为1。AIC0检测到对应的flagId=16的计数器变为1，则AIC0核解除由模板参数pipe配置的指定流水后续指令的阻塞，继续执行后续PIPE_FIX的指令，并且将计数器值减去1。</li></ul><p><strong>图5</strong> 模式4：单个AI Core中AIC与单个AIV同步（AIV进行CrossCoreSetFlag）<a id="single_ai_core_aic_single_aiv_sync_diagram"></a><br><img src="`+c+'" alt title="单AI_Core中AIC与单个AIV同步（AIV进行CrossCoreSetFlag）"></p></div></article></div>',1)])])}const S=l(i,[["render",d]]);export{u as __pageData,S as default};
